def step(x):
    print(x, end=' ')
    if x == 1:
        return
    if x % 2 == 0:
        even(x)
    else:
        odd(x)
def even(x):
    step(x // 2)
def odd(x):
    step(3 * x + 1)
step(3)

def count_down(n):
    if n == 0:
        return 'done'
    count_down(n - 1)
